public class LibraryBook {

    private final String title;
    private final String author;
    private final int year;
    private int copiesAvailable;

    public LibraryBook(String title, String author, int year, int copiesAvailable) {
        this.title = title;
        this.author = author;
        this.year = year;
        this.copiesAvailable = copiesAvailable;
    }

    public String getTitle() {
        return title;
    }

    public String getAuthor() {
        return author;
    }

    public int getYear() {
        return year;
    }

    public int getCopiesAvailable() {
        return copiesAvailable;
    }

    /** Takes one copy off the shelf. Returns false when there is none left. */
    public boolean takeCopy() {
        if (copiesAvailable <= 0) {
            return false;
        }
        copiesAvailable--;
        return true;
    }

    /** Puts a borrowed copy back on the shelf. */
    public void returnCopy() {
        copiesAvailable++;
    }

    @Override
    public String toString() {
        return title + " by " + author + " (" + year + ")";
    }
}

