import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class Catalogue {

    private final List<LibraryBook> books = new ArrayList<>();

    public boolean add(LibraryBook book) {
        if (find(book.getTitle()) != null) {
            return false;
        }
        books.add(book);
        return true;
    }

    public int size() {
        return books.size();
    }

    public LibraryBook find(String title) {
        for (LibraryBook book : books) {
            if (book.getTitle().equals(title)) {
                return book;
            }
        }
        return null;
    }

    public boolean checkOut(String title) {
        LibraryBook book = find(title);
        if (book == null) {
            return false;
        }
        return book.takeCopy();
    }

    public List<String> titlesBy(String author) {
        List<String> titles = new ArrayList<>();
        for (LibraryBook book : books) {
            if (book.getAuthor().equals(author)) {
                titles.add(book.getTitle());
            }
        }
        Collections.sort(titles);
        return titles;
    }

    public int totalCopiesAvailable() {
        int total = 0;
        for (LibraryBook book : books) {
            total += book.getCopiesAvailable();
        }
        return total;
    }
}

