public class CatalogueTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String describe(LibraryBook book) {
        return book == null ? "none" : book.toString();
    }

    static int copies(Catalogue catalogue, String title) {
        LibraryBook book = catalogue.find(title);
        return book == null ? -1 : book.getCopiesAvailable();
    }

    public static void main(String[] args) {
        Catalogue catalogue = new Catalogue();
        catalogue.add(new LibraryBook("Dune", "Frank Herbert", 1965, 2));
        catalogue.add(new LibraryBook("Emma", "Jane Austen", 1815, 1));
        catalogue.add(new LibraryBook("Persuasion", "Jane Austen", 1817, 0));

        check("size after three adds", 3, catalogue.size());
        check("adding a duplicate title is refused", false,
              catalogue.add(new LibraryBook("Dune", "Someone Else", 2001, 9)));
        check("size unchanged after the refused add", 3, catalogue.size());
        check("adding a new title is accepted", true,
              catalogue.add(new LibraryBook("Hyperion", "Dan Simmons", 1989, 1)));

        check("find an existing title", "Dune by Frank Herbert (1965)",
              describe(catalogue.find("Dune")));
        check("find an unknown title", "none", describe(catalogue.find("Nothing Here")));

        check("total copies before any loans", 4, catalogue.totalCopiesAvailable());
        check("checking out an available title", true, catalogue.checkOut("Dune"));
        check("copies left after the loan", 1, copies(catalogue, "Dune"));
        check("checking out a title with no copies", false, catalogue.checkOut("Persuasion"));
        check("checking out an unknown title", false, catalogue.checkOut("Nothing Here"));
        check("total copies after one loan", 3, catalogue.totalCopiesAvailable());

        check("titles by Jane Austen", "[Emma, Persuasion]",
              String.valueOf(catalogue.titlesBy("Jane Austen")));
        check("titles by an unknown author", "[]",
              String.valueOf(catalogue.titlesBy("Nobody At All")));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

